`).slice(0,6e3)}function gZ(){const r=document.querySelector("[data-scope-bar]");return r?r.innerText.replace(/\s+/g," ").slice(0,400):"all entities"}function mZ({text:r}){const e=[];let t=[];const n=()=>{t.length&&e.push(y.jsx("ul",{className:"mb-2 list-disc space-y-1 pl-5",children:t.map((a,i)=>y.jsx("li",{children:a},i))},e.length)),t=[]};for(const a of r.split(`
